def t(lang, key, **values):
    return ROWS[key][tuple(LANGUAGES).index(lang)].format(**values)

def route_name(lang, route):
    a, b = route.split('_')
    i = tuple(LANGUAGES).index(lang)
    return CITY[a][i] + ' → ' + CITY[b][i]


